function describe(x){if(typeof x==='string')return x;if(x?.code==='FIFO_PRIORITY')return x.message;if(x?.message&&Array.isArray(x.areas))return x.message+'\n확인이 필요한 영역: '+x.areas.join(', ')+'\n취소 후 지도 편집에서 해당 구역을 안쪽으로 옮기거나, 창고 가로·세로 크기와 외곽 형태를 조정하세요.';return safeMessage(x)}
async function api(path,options={}){
 const purchaseRead=['/purchases/google','/purchases/xlsx'].includes(path);
 const controller=new AbortController(),t=setTimeout(()=>controller.abort(),options.stream?1200000:path==='/purchases/import'?300000:purchaseRead?180000:options.blob||path.includes('/upload')||path.startsWith('/insurance/convert')||path==='/photo-backup'||path.startsWith('/photo-restore/')?120000:path==='/vin/ocr'?50000:path==='/command'?90000:20000);
 try{
  let r;try{r=await fetch('/api'+path,{...options,signal:controller.signal,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(token?{Authorization:'Bearer '+token}:{}),...options.headers}});}catch(cause){const timedOut=controller.signal.aborted;if(!timedOut)online=false;const error=Error(purchaseRead?(timedOut?'파일 읽기 대기 시간을 초과했습니다. 아직 자료 저장은 시작되지 않았습니다. 다시 가져오기를 눌러주세요.':'파일 읽기 중 연결이 끊겼습니다. 아직 자료 저장은 시작되지 않았습니다.'):path==='/purchases/import'?'전체 저장의 응답을 확인하지 못했습니다. 창을 닫지 말고 같은 가져오기 버튼을 다시 눌러 저장 결과를 확인하세요.':'서버와 연결하지 못했습니다. 저장 요청이었다면 결과를 확인하지 못한 상태입니다. 연결 복구 후 같은 요청의 처리 여부를 확인해주세요.');error.uncertain=!purchaseRead;throw error;}
  if(!r.ok){let d;try{d=await r.json()}catch{d={}};const error=Error(safeMessage(d.message||d.detail,r.status));error.status=r.status;error.requestId=/^[a-f0-9]{32}$/.test(d.request_id||'')?d.request_id:null;error.fieldErrors=d.field_errors;error.uncertain=r.status>=500;
   if(r.status===401&&path!=='/login'){token='';sessionStorage.removeItem('warehouseToken');error.message='로그인이 만료되었습니다. 작성 내용을 보존한 뒤 다시 로그인하세요.';}throw error;}
  if(options.stream){online=true;return await options.stream(r.body);}
  online=true;try{return options.blob?await r.blob():await r.json();}catch{const error=Error('서버 응답을 확인하지 못했습니다. 저장 요청의 처리 여부를 확인해주세요.');error.uncertain=true;throw error;}
 }finally{clearTimeout(t)}
}
let lastFullState=0;
async function refresh(strict=false,light=false){try{if(light&&S&&Date.now()-lastFullState<60000){const v=await api('/state/version');if(v.revision===S.revision&&v.today===S.today&&JSON.stringify(v.user)===JSON.stringify(S.user)){S.backup_warnings=v.backup_warnings;return S;}}S=await api('/state');lastFullState=Date.now();window.WarehouseNative?.setUploadSession?.(token,S.user.id);const copy=structuredClone(S);copy.vehicles.forEach(v=>{v.smart_key='';v.notes=''});localStorage.setItem('warehouseCache',JSON.stringify(copy))}catch(e){if(strict)throw e;if(!S&&token){try{S=JSON.parse(localStorage.getItem('warehouseCache'))}catch{}}if(!S||!token)throw e}return S}
async function send(action,payload,repeat=false){
 if(lastCommandOwner!==S.user.id){lastCommand=null;lastCommandOwner=S.user.id;}
 const recovery=pendingRequest(S.user.id);lastCommand=lastCommand||recovery.read();
 if(lastCommand&&!repeat){if(action===lastCommand.action&&JSON.stringify(payload)===JSON.stringify(lastCommand.payload))repeat=true;else throw Error('처리 결과를 확인하지 못한 요청이 있습니다. 관리 설정의 마지막 요청 재시도로 결과를 먼저 확인해주세요.');}
 if(!online&&!repeat)throw Error('연결을 복구한 후 확정하세요. 현재 화면은 마지막 저장 정보입니다.');
 const body=repeat?lastCommand:{command_id:crypto.randomUUID(),action,payload};if(!body)throw Error('재시도할 요청이 없습니다.');if(!['used_media','user'].includes(body.action))recovery.write(body);lastCommand=body;
 if(['used_media','user'].includes(body.action))sessionStorage.removeItem('warehousePending');else{try{sessionStorage.setItem('warehousePending',JSON.stringify(body))}catch{sessionStorage.removeItem('warehousePending')}}
 try{
  const r=await api('/command',{method:'POST',body:JSON.stringify(body)});
  try{await refresh(true);}catch{const error=Error('저장은 완료되었지만 최신 목록을 조회하지 못했습니다. 같은 요청을 재시도하면 중복 저장 없이 결과를 확인합니다.');error.uncertain=true;throw error;}
  recovery.clear();lastCommand=null;sessionStorage.removeItem('warehousePending');return r;
 }catch(e){if(online&&!e.uncertain){recovery.clear();lastCommand=null;sessionStorage.removeItem('warehousePending')}throw e}
}

