function objectRow(o){return `<div class="object-row panel"><div class="data-grid"><div><label>종류</label><select data-field="kind">${[['DOOR','문'],['AISLE','통로'],['MATERIAL','자재'],['WALL','벽']].map(([v,l])=>`<option value="${v}" ${v===o.kind?'selected':''}>${l}</option>`).join('')}</select></div>${[['label','이름'],['x','X'],['y','Y'],['width','폭'],['height','높이']].map(([k,l])=>`<div><label>${l}</label><input data-field="${k}" type="${k==='label'?'text':'number'}" value="${esc(o[k])}"></div>`).join('')}</div>${button('삭제','remove-object','','danger')}</div>`}
async function copy(text){try{await navigator.clipboard.writeText(text)}catch{const el=document.createElement('textarea');el.value=text;document.body.append(el);el.select();const ok=document.execCommand('copy');el.remove();if(!ok)throw Error('복사 권한을 확인하세요.')}toast('복사되었습니다.')}
function download(blob,name){if(window.WarehouseNative?.save){const reader=new FileReader();reader.onload=()=>window.WarehouseNative.save(name,String(reader.result).split(',')[1]);reader.readAsDataURL(blob);return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
let actionBusy=false;
document.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b)return;e.preventDefault();if(b.disabled||actionBusy||usedStock.isBusy()){if(usedStock.isBusy())toast('사진 저장 중입니다.');return;}actionBusy=true;b.disabled=true;formSafety.setBusy(b.dataset.act!=='close');try{await handle(b.dataset.act,b)}catch(e){err(e)}finally{actionBusy=false;formSafety.setBusy(false);if(b.isConnected)b.disabled=false}});
$('#modal').addEventListener('form-cancelled',()=>{window.scanContext=null;});
$('#modal').addEventListener('submit',e=>e.preventDefault());
function adaptFold(){const m=$('#modal');if(!m.open||m.dataset.inspector!=='true')return;const wide=matchMedia('(min-width:720px) and (pointer:coarse)').matches;if(wide!==m.classList.contains('inspector')){m.close();m.classList.toggle('inspector',wide);document.body.classList.toggle('inspector-open',wide);if(wide)m.show();else m.showModal();}}
$('#modal').addEventListener('close',()=>{if(!$('#modal').open)document.body.classList.remove('inspector-open')});
window.addEventListener('resize',adaptFold);

async function boot(){if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});if(token){try{await refresh();selectedDay=S?.today||dateNow()}catch{}}render();setInterval(async()=>{if(!token||polling||isMapBusy()||document.hidden||$('#modal').open)return;polling=true;try{const old=S?.revision,oldDay=S?.today,oldUser=JSON.stringify(S?.user);await refresh(false,true);if(oldUser!==JSON.stringify(S?.user)){render();return;}if(page==='map'&&S?.revision!==old)mapAssignmentRefreshPending=true;const status=$('.online');if(status){status.textContent=online?'● 연결됨':'● 오프라인 조회';status.classList.toggle('off',!online)}if(page!=='parts'&&(S?.revision!==old||oldDay!==S?.today||(page==='map'&&mapAssignmentRefreshPending))&&!isMapBusy()&&!$('#modal').open&&![...document.querySelectorAll('input,textarea,select')].includes(document.activeElement)){renderPage();mapAssignmentRefreshPending=false}}catch{}finally{polling=false}},5000)}
const usedStock=createUsedStock({api,send,modal,button,esc,field,toast,download,detail,user:()=>S.user,today:()=>S.today,vehicle,render:renderPage,masters,formSafety});
formSafety.setDirtyProbe(()=>usedStock.isDirty()||partsRulesDirty());
const notifications=installNotifications({api,identity:()=>token&&S?.user.role!=='ubis'?token:'',modal,button,esc,toast});
boot();

window.handleWarehouseBack=()=>{const overlay=[...document.querySelectorAll('dialog[data-photo-overlay][open]')].at(-1);if(overlay){overlay.dispatchEvent(new Event('photo-back'));return true;}if(!$('#modal').open)return false;formSafety.close();return true;};

installVehicleHold({eligible:()=>page==='map'&&!moving&&!$('#modal').open&&['admin','worker'].includes(S?.user.role),begin:id=>{if(!vehicle(id)?.stay_id)return;if(editMap){const card=$$('.slot').find(el=>el.dataset.vehicle===id);const r=card?.getBoundingClientRect();if(card&&r)card.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:r.left+r.width/2,clientY:r.top+r.height/2}));return;}moving=id;toast('이동하거나 맞바꿀 자리를 선택하세요.');renderPage();},cancelMove:()=>{if(moving&&!$('#modal').open){moving=null;renderPage();}}});
